index fafa4bf90b..e103f48eb6 100644
--- a/src/compiler/turbofan-typer.cc
+++ b/src/compiler/turbofan-typer.cc
@@ -714,21 +714,22 @@ Type Typer::Visitor::ToString(Type type, Typer* t) {
   type = ToPrimitive(type, t);
   if (type.Is(Type::String())) return type;
   return Type::String();
 }

 // Type checks.

 Type Typer::Visitor::ObjectIsArrayBufferView(Type type, Typer* t) {
   // TODO(turbofan): Introduce a Type::ArrayBufferView?
   CHECK(!type.IsNone());
-  if (!type.Maybe(Type::OtherObject())) return t->singleton_false_;
+  if (type.Is(Type::TypedArray())) return t->singleton_true_;
+  if (!type.Maybe(Type::TypedArray())) return t->singleton_false_;
   return Type::Boolean();
 }

 Type Typer::Visitor::ObjectIsBigInt(Type type, Typer* t) {
   CHECK(!type.IsNone());
   if (type.Is(Type::BigInt())) return t->singleton_true_;
   if (!type.Maybe(Type::BigInt())) return t->singleton_false_;
   return Type::Boolean();
 }

